import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
DATE='2026-10-11'
packet={'sources':[],'guides':[],'glossary':[],'mechanisms':[]}
def source(id,title,url,sections,preview,kind='Official context page'):
 packet['sources'].append({'id':id,'title':title,'url':url,'sourceType':'context','sourceTier':'CONTEXT','access':'Public full page','preview':preview,'reviewState':'context_source','retrievedAt':DATE,'sourceKind':kind,'locators':[{'section':section,'table_figure':None,'basis':'Full official source page verified on '+DATE} for section in sections]})
def sentence(text,*sources): return {'text':text,'sources':list(sources)}
def ids(ss): return list(dict.fromkeys(s for x in ss for s in x['sources']))
def section(id,label,*ss,questions=None):
 return {'id':id,'label':label,'title':'','paragraph':' '.join(x['text'] for x in ss),'sources':ids(ss),'sentences':list(ss),'questions':questions or []}
def question(id,title,*ss): return {'id':id,'question':title,'answer':' '.join(x['text'] for x in ss),'sources':ids(ss),'sentences':list(ss)}
def mblock(*ss): return {'text':' '.join(x['text'] for x in ss),'sourceIds':ids(ss),'sentences':list(ss)}
def mq(id,title,*ss): return {'id':id,'title':title,**mblock(*ss)}
def guide(id,slug,title,type,description,sections,faqs,related,entity=None,aliases=None):
 g={'id':id,'slug':slug,'title':title,'type':type,'description':description,'scope':description,'topicIds':[],'sections':sections,'faqs':faqs,'sourceIds':list(dict.fromkeys(s for p in [*sections,*faqs] for s in p['sources'])),'related':related,'synthesisIds':[],'coverageLabel':''}
 if entity: g['entityId']=entity
 if aliases: g['aliases']=aliases
 packet['guides'].append(g); return g

def term(slug,title,meaning,context,examples,aliases=None):
 ss={'meaning':[meaning],'context':[context],'examples':[examples]}
 t={'slug':slug,'title':title,**{k:v[0]['text'] for k,v in ss.items()},'sources':ids([meaning,context,examples]),'sentenceMaps':ss}
 if aliases: t['aliases']=aliases
 packet['glossary'].append(t)

