term('hedgehog-pathway','Hedgehog pathway',sentence('The Hedgehog pathway is a cell-signaling system that carries messages from the cell surface to the nucleus and helps regulate growth and development.','CTX-TERM-HEDGEHOG-SIGNALING-PATHWAY'),sentence('It also contributes to stem-cell maintenance and tissue repair; abnormal signaling can participate in cancer.','CTX-TERM-HEDGEHOG-SIGNALING-PATHWAY'),sentence('A Hedgehog inhibitor targets this signaling route. Whether a particular drug helps a particular cancer still requires clinical testing.','CTX-TERM-HEDGEHOG-SIGNALING-PATHWAY','CTX-GUIDE-2'),['Hedgehog signaling','Hedgehog signaling pathway','Hedgehog pathway inhibition'])
term('cholesterol-transport-inhibition','Cholesterol transport inhibition',sentence('Cholesterol transport inhibition means interfering with the movement of cholesterol between cellular locations.','CTX-TERM-NPC1'),sentence('NPC1 is one protein involved in moving cholesterol and other lipids within cells; impaired function can trap lipids in the wrong compartments.','CTX-TERM-NPC1'),sentence('A study of intracellular cholesterol transport asks a different question from a blood cholesterol test. Disrupted transport can damage cells, so inhibition is not inherently beneficial.','CTX-TERM-NPC1'),['cholesterol trafficking inhibition','inhibition of cholesterol transport','inhibition of cholesterol trafficking'])
term('apoptosis','Apoptosis',sentence('Apoptosis is a controlled sequence of events that ends in a cell’s death, often called programmed cell death.','CTX-TERM-APOPTOSIS'),sentence('It helps remove cells that are abnormal or no longer needed, and some cancer cells evade it.','CTX-TERM-APOPTOSIS'),sentence('Showing apoptosis in cancer cells is a mechanistic observation; a patient trial is needed to determine whether a treatment improves health.','CTX-TERM-APOPTOSIS','CTX-GUIDE-2'),['programmed cell death'])
term('autophagy','Autophagy',sentence('Autophagy is cellular breakdown and recycling of proteins and other internal material, including damaged components.','CTX-TERM-AUTOPHAGY'),sentence('Its effects depend on context: recycling can protect normal cells, but established cancer cells may also use it to survive stress.','CTX-TERM-AUTOPHAGY'),sentence('An increase in autophagy should therefore be interpreted alongside the disease model and outcome, rather than treated as an automatic health benefit.','CTX-TERM-AUTOPHAGY'))
term('biofilm','Biofilm',sentence('A biofilm is a community of microbes embedded in a surrounding matrix that the microbes produce.','CTX-TERM-BIOFILM'),sentence('Biofilms can contain bacteria or fungi and occur on body surfaces, such as teeth, as well as on objects.','CTX-TERM-BIOFILM'),sentence('Preventing a biofilm from forming and disrupting an existing biofilm are distinct experimental questions; neither alone establishes a clinical treatment benefit.','CTX-TERM-BIOFILM','CTX-GUIDE-2'),['biofilms','biofilm destruction','biofilm disruption'])
term('candida-albicans','Candida albicans',sentence('Candida albicans is one species of Candida, a group of yeasts that can live on the body without causing symptoms.','CTX-CANDIDA-CDC'),sentence('Candida overgrowth can cause candidiasis; infection severity depends on the body site and the person’s risk factors.','CTX-CANDIDA-CDC'),sentence('Finding Candida without symptoms does not by itself establish vaginal infection or a need for antifungal treatment.','CTX-CANDIDA-GUIDELINE'),['C. albicans'])
term('hyphae','Hyphae',sentence('Hyphae are microscopic fungal filaments; a network of these filaments forms a mycelium.','CTX-TERM-HYPHAE'),sentence('In symptomatic vaginal candidiasis, microscopy may reveal budding yeast, hyphae or pseudohyphae as part of diagnosis.','CTX-CANDIDA-GUIDELINE'),sentence('A change in fungal shape is a different observation from symptom resolution or clearance of infection in a patient.','CTX-CANDIDA-GUIDELINE'),['hypha','hyphal','hyphal states','hyphal formation'])
term('angiogenesis','Angiogenesis',sentence('Angiogenesis is the formation of blood vessels.','CTX-TERM-ANGIOGENESIS'),sentence('Tumors can stimulate nearby cells and tissues to grow vessels that support further tumor growth.','CTX-TERM-ANGIOGENESIS'),sentence('Anti-angiogenic activity describes an effect on vessel formation; it does not by itself quantify a survival benefit.','CTX-TERM-ANGIOGENESIS','CTX-GUIDE-2'),['anti-angiogenic','antiangiogenic','antiangiogenesis'])
term('hypoxia','Hypoxia',sentence('Hypoxia means that a tissue has a reduced supply of oxygen.','CTX-TERM-HYPOXIA'),sentence('In a tumor, the degree of hypoxia can influence how the tumor responds to treatment.','CTX-TERM-HYPOXIA'),sentence('Measuring oxygen in the relevant tissue addresses hypoxia more directly than assuming that a change in blood flow corrected it.','CTX-TERM-HYPOXIA','CTX-TERM-OXYGEN'))
term('oxygenation','Oxygenation',sentence('Oxygenation describes oxygen reaching blood or tissue; inhaled oxygen normally moves from the lungs into blood and then to tissues.','CTX-TERM-OXYGEN'),sentence('Local oxygenation concerns a particular tissue, while hypoxia describes an inadequate oxygen supply there.','CTX-TERM-OXYGEN','CTX-TERM-HYPOXIA'),sentence('A claim of increased local oxygenation needs a measurement in the relevant tissue, rather than a blood-flow change alone.','CTX-TERM-OXYGEN','CTX-TERM-HYPOXIA'),['local oxygenation','increased local oxygenation'])
term('mtor','mTOR',sentence('mTOR, the mechanistic target of rapamycin, is a protein kinase involved in cell growth, division and survival.','CTX-TERM-MTOR'),sentence('Some cancer cells have increased mTOR activity, making this pathway a target for treatment research.','CTX-TERM-MTOR'),sentence('Rapamycin is another name for sirolimus. Its interaction with mTOR explains a biological target, while clinical effects depend on the condition and treatment tested.','CTX-TERM-MTOR','AGING-SIROLIMUS-LABEL','CTX-GUIDE-2'),['mechanistic target of rapamycin','mammalian target of rapamycin'])
term('pde5','PDE5',sentence('Phosphodiesterase type 5, or PDE5, is an enzyme that breaks down cyclic GMP, a signal involved in smooth-muscle relaxation.','D31-CIALIS-LABEL'),sentence('PDE5 inhibition preserves this signal and can increase blood flow in responsive tissues.','D31-CIALIS-LABEL'),sentence('Tadalafil inhibits PDE5, but its erectile effect still requires sexual stimulation to trigger nitric-oxide signaling.','D31-CIALIS-LABEL'),['phosphodiesterase type 5','phosphodiesterase-5','PDE5 inhibition','PDE5 inhibitor','PDE5 inhibitors'])
term('ergosterol','Ergosterol',sentence('Ergosterol is a steroid found in fungi and is part of the sterol pathway targeted by azole antifungals.','CTX-TERM-ERGOSTEROL','CTX-D34-LABEL'),sentence('Fluconazole inhibits the fungal enzyme lanosterol 14-alpha-demethylase, reducing the conversion of lanosterol toward ergosterol.','CTX-D34-LABEL'),sentence('This fungal sterol mechanism is distinct from inhibiting cholesterol transport inside human cells.','CTX-D34-LABEL','CTX-TERM-NPC1'))

# Explainer: definitional, translational and regulatory context, no unsourced outcome claims.
rsections=[
 section('overview','Overview',sentence('Drug repurposing investigates whether an existing medicine or investigational compound can treat a different condition.','CTX-REPURPOSING-NCATS','CTX-REPURPOSING-SCREENING'),sentence('The starting point is prior knowledge about the compound; the new use remains a question to test.','CTX-REPURPOSING-SCREENING')),
 section('rationale','Rationale',sentence('Existing compounds may already have manufacturing, laboratory and human data, allowing researchers to build on earlier development.','CTX-REPURPOSING-SCREENING'),sentence('That can shorten some development steps, although a new indication still needs evidence and may face funding barriers, especially for off-patent medicines.','CTX-REPURPOSING-DEVELOPMENT')),
 section('mechanisms','Mechanisms',sentence('A mechanism of action describes the biological steps through which a drug acts. Researchers can look for a relevant target or disease process, screen compounds, and confirm activity in cells or animals before clinical testing.','CTX-REPURPOSING-SCREENING'),sentence('Examples of biological questions include effects on the Hedgehog pathway, apoptosis, autophagy or angiogenesis. Each names a process to investigate, not a promise that changing it will improve a disease.','CTX-TERM-HEDGEHOG-SIGNALING-PATHWAY','CTX-TERM-APOPTOSIS','CTX-TERM-AUTOPHAGY','CTX-TERM-ANGIOGENESIS','CTX-GUIDE-2')),
 section('evidence','Evidence',sentence('Basic research tests biological ideas; translational research develops them toward possible interventions; clinical trials evaluate effects in people.','CTX-GUIDE-2'),sentence('Controlled trials compare a treatment group with standard care or an inactive control, helping distinguish treatment effects from what would otherwise happen.','CTX-GUIDE-4'),sentence('For a repurposing claim, read the population, treatment, comparison and measured outcome together. A laboratory pathway change answers a different question from improved symptoms or survival.','CTX-GUIDE-2','CTX-GUIDE-4')),
 section('status','Status',sentence('Off-label use means prescribing an approved drug outside its approved indication, route or dose. In the United States, clinicians may do this when medically appropriate, but FDA has not determined safety and effectiveness for that unapproved use.','CTX-off-label-1'),sentence('Repurposing is the research and development question; off-label use is a prescribing status. A successful repurposing program can seek a new approved indication.','CTX-REPURPOSING-NCATS','CTX-off-label-1','CTX-REPURPOSING-DEVELOPMENT')),
 section('safety','Safety',sentence('Approval for one use does not mean a medicine is free of risks. The intended condition, dose and route matter when weighing benefits and harms.','CTX-off-label-1'),sentence('Metformin’s established role in type 2 diabetes, for example, does not remove its kidney-related restrictions or lactic-acidosis warning.','MF-LABEL-2025')),
 section('reading','Reading',sentence('Ask what the medicine is already approved for, what studies support the proposed use, how it compares with available treatments, and what harms are possible.','CTX-off-label-1'),sentence('Then examine study design and outcomes: an experimental result is most useful when the comparison and the question it answers are clear.','CTX-GUIDE-4'))
]
for section_record, heading in zip(rsections, ['Overview', 'Why repurpose a drug?', 'Mechanisms', 'Evidence', 'Approval and off-label use', 'Safety', 'Reading a repurposing claim']):
 section_record['title']=heading

guide('G-DRUG-REPURPOSING','/drug-repurposing','Drug repurposing','Explainer','How existing medicines become candidates for new uses, and how mechanisms, clinical evidence and approval fit together.',rsections,[question('repurposing-approved','Does an approved medicine already have evidence for every new use?',sentence('No. FDA approval concerns specified uses; a different indication needs its own assessment of safety and effectiveness.','CTX-off-label-1')),question('repurposing-mechanism','Why include mechanisms when clinical outcomes matter?',sentence('Mechanisms help formulate and test a rationale. Clinical studies then assess whether that rationale translates into useful effects in people.','CTX-REPURPOSING-SCREENING','CTX-GUIDE-2'))],['G-READING','G-METFORMIN','G-DRUG-D07'])

# New condition foundation. No invented repurposing evidence rows.
csections=[
 section('c31-overview','Overview',sentence('Type 2 diabetes is a condition in which blood glucose remains too high because tissues do not respond adequately to insulin and the pancreas cannot supply enough insulin to compensate.','COND-C31-NIDDK'),sentence('Over time, diabetes can damage the eyes, kidneys, nerves and cardiovascular system.','COND-C31-NIDDK')),
 section('c31-options','Options',sentence('Management combines healthy daily habits, monitoring and medicines selected for the person’s glucose levels and other health conditions.','COND-C31-MANAGEMENT'),sentence('Metformin is an established glucose-lowering treatment for type 2 diabetes, rather than an experimental repurposing use in this condition.','MF-LABEL-2025'),questions=[question('c31-metformin','What is metformin’s role here?',sentence('Metformin is labeled as an addition to diet and exercise to improve blood glucose control in type 2 diabetes.','MF-LABEL-2025')),question('c31-individualization','Why do people with type 2 diabetes receive different medicines?',sentence('Treatment choices depend on glucose control, other illnesses, medicine costs and access, as well as the person’s circumstances.','COND-C31-MANAGEMENT'))]),
 section('c31-evidence','Evidence',sentence('Glucose control, blood pressure and cholesterol management contribute to reducing diabetes-related health risks.','COND-C31-NIDDK'),sentence('This page explains established disease context and metformin’s labeled action; it does not provide a comparative synthesis of repurposed treatments for type 2 diabetes.','COND-C31-NIDDK','MF-LABEL-2025')),
 section('c31-safety','Safety',sentence('Monitoring helps identify glucose levels that are too high or too low, particularly when medicines are used.','COND-C31-MANAGEMENT'),sentence('Metformin has a lactic-acidosis warning and is contraindicated in severe renal impairment.','MF-LABEL-2025')),
 section('c31-comparisons','Comparisons',sentence('Type 1 diabetes involves immune destruction of insulin-producing cells. Type 2 diabetes involves ineffective insulin action together with an insulin supply that cannot meet the body’s needs.','COND-C31-NIDDK'),sentence('Prediabetes describes elevated glucose below the diagnostic range for diabetes; it is a different stage, not another name for established type 2 diabetes.','COND-C31-NIDDK')),
 section('c31-connections','Connections',sentence('Metformin’s glucose-lowering action provides an established-use reference when reading its drug-repurposing research.','MF-LABEL-2025','CTX-REPURPOSING-NCATS'),sentence('An effect on glucose control should be distinguished from a finding about a different disease or clinical outcome.','CTX-GUIDE-2'))
]
c=guide('G-CONDITION-C31','/conditions/type-2-diabetes','Type 2 diabetes','Condition','Insulin resistance, blood glucose and the established role of metformin, with links to the wider drug-repurposing evidence.',csections,[question('c31-age','Can type 2 diabetes occur in younger people?',sentence('Yes. It can develop at any age, including childhood.','COND-C31-NIDDK')),question('c31-metformin-insulin','Does metformin work by making the pancreas release more insulin?',sentence('Its labeled action is to reduce liver glucose production and intestinal absorption and improve glucose uptake; insulin secretion remains unchanged.','MF-LABEL-2025'))],['G-METFORMIN','G-DRUG-REPURPOSING'],'C31',['type 2 diabetes mellitus','T2D','T2DM'])
packet['mechanisms'].append({'conditionId':'C31','guideIds':['G-CONDITION-C31'],'summary':mblock(sentence('Insulin normally helps glucose enter cells. In type 2 diabetes, reduced responsiveness and insufficient compensation leave more glucose in the blood.','COND-C31-NIDDK')),'questions':[mq('c31-mechanism-metformin','How does metformin address glucose handling?',sentence('Metformin reduces liver glucose output and intestinal glucose absorption while increasing glucose uptake and use in tissues.','MF-LABEL-2025'))]})

# New drug foundation. Biological activity and standard infection uses are kept distinct from novel-use outcomes.
dsections=[
 section('d34-overview','Overview',sentence('Fluconazole is a triazole antifungal medicine used for susceptible fungal infections, including Candida infections and fungal meningitis.','CTX-D34-MEDLINEPLUS'),sentence('It slows fungal growth; its established infection uses do not establish benefit for unrelated diseases.','CTX-D34-MEDLINEPLUS','CTX-off-label-1')),
 section('d34-benefits','Benefits',sentence('Established uses include vaginal, mouth and esophageal candidiasis, cryptococcal meningitis, and candidiasis prevention in selected bone-marrow-transplant settings.','CTX-D34-LABEL'),questions=[question('d34-positive-culture','Does detecting Candida always mean treatment is needed?',sentence('No. For vaginal Candida, a positive culture without symptoms or signs is not by itself an indication for treatment.','CTX-CANDIDA-GUIDELINE')),question('d34-recurrence','Does suppressing recurrent vaginal candidiasis guarantee a lasting cure?',sentence('Suppressive therapy can control recurrent vaginal candidiasis but is rarely curative over the long term.','CTX-CANDIDA-GUIDELINE'))]),
 section('d34-safety','Safety',sentence('Headache, diarrhea, stomach discomfort and dizziness can occur; severe rash, allergic reactions and liver-related symptoms require medical attention.','CTX-D34-MEDLINEPLUS'),sentence('Pregnancy, heart rhythm problems, kidney disease and liver disease affect its safe use.','CTX-D34-MEDLINEPLUS')),
 section('d34-contraindications','Contraindications',sentence('Known fluconazole hypersensitivity is a contraindication; certain QT-prolonging combinations, including pimozide and quinidine, are also contraindicated.','CTX-D34-LABEL')),
 section('d34-interactions','Interactions',sentence('Fluconazole inhibits CYP2C9, CYP2C19 and CYP3A4, potentially increasing exposure to other medicines.','CTX-D34-LABEL'),sentence('Prescription medicines, over-the-counter products and supplements should be checked together for interactions.','CTX-D34-MEDLINEPLUS')),
 section('d34-dosing','Dosing',sentence('Treatment duration ranges from a single dose to weeks or longer, depending on the infection and response; tablets and oral suspension are available.','CTX-D34-MEDLINEPLUS'),sentence('Shake oral suspension well before each use; unused liquid is discarded after 14 days according to the patient information.','CTX-D34-MEDLINEPLUS'),sentence('A regimen for one infection should not be assumed appropriate for another indication.','CTX-off-label-1')),
 section('d34-results','Results',sentence('For vaginal candidiasis, clinical improvement and negative fungal cultures are distinct outcomes. CDC reports that azole treatment achieves both in most patients who complete treatment for uncomplicated disease.','CTX-CANDIDA-GUIDELINE'),sentence('Those infection outcomes do not measure biofilm destruction or benefit in a non-fungal condition.','CTX-CANDIDA-GUIDELINE','CTX-GUIDE-2')),
 section('d34-quality','Quality',sentence('Prescribing information supports established antifungal uses, while candidiasis guidance distinguishes uncomplicated infection from recurrent or resistant disease.','CTX-D34-LABEL','CTX-CANDIDA-GUIDELINE'),sentence('These sources do not establish fluconazole’s effectiveness for non-fungal conditions; that requires clinical evidence for the proposed use.','CTX-GUIDE-2','CTX-off-label-1')),
 section('d34-status','Status',sentence('US labeling covers specified fungal infections and selected prophylaxis; a proposed new use requires its own evidence assessment.','CTX-D34-LABEL','CTX-off-label-1')),
 section('d34-evidence','Evidence',sentence('Susceptibility varies by organism; Candida krusei is considered resistant to fluconazole.','CTX-D34-LABEL'),sentence('Persistent or recurrent vaginal symptoms call for reassessment, including consideration of resistant or non-albicans Candida.','CTX-CANDIDA-GUIDELINE')),
 section('d34-connections','Connections',sentence('Candida albicans, hyphae and biofilm describe an organism, a fungal form and a microbial community, respectively. These terms describe different targets of investigation.','CTX-CANDIDA-CDC','CTX-TERM-HYPHAE','CTX-TERM-BIOFILM'))
]
d=guide('G-DRUG-D34','/drugs/fluconazole','Fluconazole','Drug','Antifungal uses, ergosterol synthesis, resistance and the distinction between infection treatment and proposed new uses.',dsections,[question('d34-antibacterial','Is fluconazole an antibacterial medicine?',sentence('It is an antifungal: it slows the growth of fungi that cause infection.','CTX-D34-MEDLINEPLUS')),question('d34-hypha-efficacy','Does observing fewer hyphae establish a clinical cure?',sentence('No. Microscopy findings, symptoms and culture results provide different information in candidiasis assessment.','CTX-CANDIDA-GUIDELINE'))],['G-DRUG-D07','G-DRUG-REPURPOSING'],'D34',['Diflucan'])
d['originalUse']={'text':'Treatment and selected prevention of susceptible fungal infections.','sourceIds':['CTX-D34-LABEL']}
packet['mechanisms'].append({'drugId':'D34','guideIds':['G-DRUG-D34'],'originalAction':mblock(sentence('Fluconazole inhibits fungal lanosterol 14-alpha-demethylase, disrupting production of ergosterol.','CTX-D34-LABEL')),'summary':mblock(sentence('Altered fungal sterols are associated with growth inhibition. This is an established antifungal mechanism, not evidence of benefit in another disease.','CTX-D34-LABEL','CTX-GUIDE-2')),'questions':[mq('d34-mechanism-resistance','Why can an azole-sensitive target fail to translate into activity?',sentence('Resistance can involve altered target enzymes or transporters that remove drug from fungal cells.','CTX-D34-LABEL')),mq('d34-mechanism-endpoints','Does ergosterol inhibition establish biofilm destruction?',sentence('No. A biofilm is a microbial community within a matrix; demonstrating activity against its formation or an established biofilm requires an experiment addressing that structure.','CTX-TERM-BIOFILM','CTX-GUIDE-2'))]})

# Include mechanism references in their guide's citation inventory.
for g in packet['guides']:
 for m in packet['mechanisms']:
  if g['id'] not in m.get('guideIds',[]): continue
  for b in [m.get('originalAction'),m.get('summary'),*m.get('questions',[])]:
   if b:
    for sid in b['sourceIds']:
     if sid not in g['sourceIds']:g['sourceIds'].append(sid)
(ROOT/'data/wiki-foundations.json').write_text(json.dumps(packet,ensure_ascii=False,indent=2)+'\n')
print({k:len(v) for k,v in packet.items()})
